class BIOTagger:
    def __init__(self):
        pass

    def tag_entities(self, words: list[str],
                     tags: list[str]) -> list[dict]:
        entities = []
        current = None
        for i, (word, tag) in enumerate(zip(words, tags)):
            if tag.startswith("B-"):
                if current:
                    entities.append(current)
                current = {'words': [word], 'type': tag[2:], 'start': i, 'end': i}
            elif tag.startswith("I-"):
                etype = tag[2:]
                if current and current['type'] == etype:
                    current['words'].append(word)
                    current['end'] = i
                else:
                    if current:
                        entities.append(current)
                    current = {'words': [word], 'type': etype, 'start': i, 'end': i}
            else:
                if current:
                    entities.append(current)
                current = None
        if current:
            entities.append(current)
        return [{'entity': ' '.join(e['words']), 'type': e['type'],
                 'start': e['start'], 'end': e['end']} for e in entities]

    def validate_tags(self, tags: list[str]) -> bool:
        prev = "O"
        for tag in tags:
            if tag.startswith("I-"):
                if prev == "O" or prev[2:] != tag[2:]:
                    return False
            prev = tag
        return True


# Test it:
tagger = BIOTagger()

words = ["Elon", "Musk", "founded", "SpaceX", "in", "California"]
tags = ["B-PER", "I-PER", "O", "B-ORG", "O", "B-LOC"]

entities = tagger.tag_entities(words, tags)
for e in entities:
    print(f"{e['entity']} ({e['type']})")

print(tagger.validate_tags(["B-PER", "I-PER", "O"]))
print(tagger.validate_tags(["I-PER", "O"]))
print(tagger.validate_tags(["B-PER", "I-ORG"]))
